  "translations": {
    "1": "Ты вернулся, <CHARNAME>. Орин ждал тебя внизу.",
    "2": "Селена, ты была права. Я слишком поспешно обвинил его.",
    "3": "Я пообещал Селене, что помогу ей. Орин должен извиниться перед ней.",
    "4": "Орин, ты был ранен? Я волновалась за тебя.",
    "5": "Ты спас её, странник. Я обязан тебе жизнью.",
    "6": "Тогда сдержи своё обещание, Орин. Встретимся на рассвете."
  }
}

